// Jede Mail aus den Posteingängen für das Portal aufbereiten. Das Portal entscheidet, ob es eine Unzustellbar-Meldung,
// eine Abwesenheitsnotiz oder eine Antwort auf eine gesendete E-Mail ist – alles andere verwirft es, gespeichert wird kein Inhalt.
// Bereits gemeldete Mails (Knoten „Gemeldet merken“) und Mails älter als TAGE werden übersprungen.
const TAGE = 3;
const merk = $getWorkflowStaticData('global');
const gemeldet = new Set(merk.gemeldet || []);

const adressen = (l) => (Array.isArray(l) ? l : l ? [l] : [])
  .map((x) => (typeof x === 'string' ? x : x.name ? x.name + ' <' + (x.address || '') + '>' : x.address || '')).filter(Boolean).join(', ');
const text = (v) => (v == null ? '' : typeof v === 'string' ? v : Array.isArray(v) ? v.map(text).join(' ') : typeof v === 'object' ? (v.text || v.address || '') : String(v));

const aus = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const env = j.envelope || {};
  // Kopfzeilen: je nach Version des IMAP-Knotens als Objekt oder als Rohtext
  let h = j.headers || {};
  if (typeof h === 'string') {
    const roh = h.replace(/\r?\n[ \t]+/g, ' ');
    h = {};
    for (const z of roh.split(/\r?\n/)) { const m = /^([^:\s]+):\s*(.*)$/.exec(z); if (m) h[m[1].toLowerCase()] = m[2]; }
  }
  const kopf = (n) => text(h[n] ?? h[n.toLowerCase()] ?? Object.entries(h).find(([k]) => k.toLowerCase() === n)?.[1]);
  const datum = env.date || kopf('date') || '';
  const zeit = datum ? new Date(datum).getTime() : NaN;
  if (!Number.isNaN(zeit) && zeit < Date.now() - TAGE * 86400000) continue;
  const message_id = text(env.messageId) || kopf('message-id');
  const schluessel = message_id || [j.mailboxPath || 'INBOX', j.uid, datum].join('|');
  if (gemeldet.has(schluessel)) continue;
  const html = text(j.htmlContent || j.textHtml).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
  aus.push({ json: {
    schluessel,
    postfach: adressen(env.to) || kopf('delivered-to') || kopf('to'),
    von: adressen(env.from) || kopf('from'),
    betreff: text(env.subject) || kopf('subject'),
    datum: datum ? String(datum) : '',
    message_id,
    in_reply_to: text(env.inReplyTo) || kopf('in-reply-to'),
    references: kopf('references'),
    auto: kopf('auto-submitted'),
    text: (text(j.textContent || j.textPlain) || html).slice(0, 50000),
  } });
}
return aus;

// Nach erfolgreicher Meldung ans Portal: Mails merken, damit sie beim nächsten Abruf nicht erneut gemeldet werden.
// (Schlägt die Meldung fehl, bleibt nichts gemerkt – der nächste Lauf versucht es wieder; das Portal verbucht nichts doppelt.)
const merk = $getWorkflowStaticData('global');
const neu = $('Mail aufbereiten').all().map((i) => i.json.schluessel).filter(Boolean);
merk.gemeldet = [...new Set([...(merk.gemeldet || []), ...neu])].slice(-3000);
return $input.all();
